<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Free trial policy | CareSys</title><link rel="stylesheet" href="/assets/caresys.css"></head><body><main class="content" style="max-width:800px;margin:auto"><section class="card"><div class="standalone-notification-bar"><?= view('components/notification_menu',['w'=>$w]) ?></div><h1>Agency free trial policy</h1><p>Platform administrators can set the free period for future agency trials. Existing trial dates stay fixed.</p><?php if(session('message')): ?><p role="status"><?= esc(session('message')) ?></p><?php endif ?><?php if(session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?><form method="post" action="/app/billing-policy"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$policy['version'] ?>"><label for="trial-days">Free trial days</label><select name="trial_days" id="trial-days"><?php for($day=1;$day<=365;$day++): ?><option value="<?= $day ?>" <?= (int)$policy['trial_days']===$day?'selected':'' ?>><?= $day ?> days</option><?php endfor ?></select><p><button>Save free trial policy</button></p></form><p><a href="/app/platform">Back to platform administration</a></p></section></main></body></html>
